namespace { void err(ExprPackageStringView* e,const char* s){if(e)*e=ExprPackageStringView{s, std::strlen(s)};} bool mono(const ExprHostApi*,const ExprPackageValue*,size_t n,ExprPackageValue*r,ExprPackageStringView*e){if(n){err(e,"monotonicMillis expects no arguments");return false;}r->kind=EXPR_PACKAGE_VALUE_I64;r->as.i64_value=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count();return true;} bool unixms(const ExprHostApi*,const ExprPackageValue*,size_t n,ExprPackageValue*r,ExprPackageStringView*e){if(n){err(e,"unixMillis expects no arguments");return false;}r->kind=EXPR_PACKAGE_VALUE_I64;r->as.i64_value=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();return true;} bool sleepms(const ExprHostApi*,const ExprPackageValue*a,size_t n,ExprPackageValue*r,ExprPackageStringView*e){if(n!=1||a[0].kind!=EXPR_PACKAGE_VALUE_I64||a[0].as.i64_value<0){err(e,"sleepMillis expects a non-negative i64");return false;}std::this_thread::sleep_for(std::chrono::milliseconds(a[0].as.i64_value));r->kind=EXPR_PACKAGE_VALUE_NULL;return true;} constexpr ExprPackageFunctionExport f[]={{"monotonicMillis","fn() -> i64",0,mono},{"unixMillis","fn() -> i64",0,unixms},{"sleepMillis","fn(i64) -> void",1,sleepms}}; constexpr ExprPackageRegistration x={3,"github","time",f,3,nullptr,0}; } extern "C" const ExprPackageRegistration* exprRegisterPackage(){return &x;}
